        this.serverCodecConfigurer = serverCodecConfigurer;
    }

    private void initAppType() {
        System.setProperty(SentinelConfig.APP_TYPE_PROP_KEY, ConfigConstants.APP_TYPE_SCG_GATEWAY);
    }

    private void initFallback() {
        FallbackProperties fallbackProperties = gatewayProperties.getFallback();
        if (fallbackProperties == null || StringUtil.isBlank(fallbackProperties.getMode())) {
            return;
        }
        if (ConfigConstants.FALLBACK_MSG_RESPONSE.equals(fallbackProperties.getMode())) {
            String responseBody = fallbackProperties.getResponseBody();
            if (StringUtil.isNotBlank(responseBody) && responseBody != null) {
                GatewayCallbackManager.setBlockHandler((exchange, t) -> ServerResponse.status(fallbackProperties.getResponseStatus()).contentType(MediaType.valueOf(fallbackProperties.getContentType())).body(fromValue(responseBody)));
                logger.info("[Sentinel SpringCloudGateway] using AnonymousBlockRequestHandler, responseStatus: " + fallbackProperties.getResponseStatus() + ", responseBody: " + responseBody);
            }
        }
        String redirectUrl = fallbackProperties.getRedirect();
        if (ConfigConstants.FALLBACK_REDIRECT.equals(fallbackProperties.getMode()) && StringUtil.isNotBlank(redirectUrl)) {
            GatewayCallbackManager.setBlockHandler(new RedirectBlockRequestHandler(redirectUrl));
            logger.info("[Sentinel SpringCloudGateway] using RedirectBlockRequestHandler, redirectUrl: " + redirectUrl);
        }
    }

