    @Override
    protected SQLExpr primaryDistinct(SQLExpr sqlExpr) {
        Lexer.SavePoint mark = lexer.mark();
        sqlExpr = new SQLIdentifierExpr(lexer.stringVal());
        lexer.nextToken();
