    @Override
    protected String parseSelectItemAlias(String alias) {
        boolean specialChar = false;
        for (int i = 0; i < alias.length(); ++i) {
            char ch = alias.charAt(i);
            if (ch == '`') {
                specialChar = true;
                break;
            }
        }
        if (specialChar) {
            alias = alias.replaceAll("`", "``");
            alias = '`' + alias + '`';
        }
        return alias;
    }

